const test = require('node:test');
const assert = require('node:assert/strict');
const WebhookManager = require('../utils/webhook-manager');

test('delivers a queued response to a later-registered waiting node', async () => {
  const manager = new WebhookManager();
  const sessionKey = 'sms:campaign_1:+254700000000';
  const queuedResponse = { content: 'yes', from: '+254700000000' };
  let delivered = null;

  manager.queuePendingResponse(sessionKey, queuedResponse);

  await new Promise((resolve) => {
    manager.registerWaitingNode(sessionKey, (response) => {
      delivered = response;
      resolve();
    });
  });

  assert.deepEqual(delivered, queuedResponse);
});
